contracts/BridgeAirlock.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IRunnerRecords {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

interface IGuardInbound {
    function inbound(bytes32 route, address to, uint256 amount) external;
    function guardian(address who) external view returns (bool);
}

/// ThreatRegistry's views (Reason as its uint8 value). is*Held: once the flag is
/// the registry's holdDelay old (e.g. 10 minutes), or at once through its fast
/// lane or a guardian's holdNow. is*Enforced: once the flag is the registry's
/// enforceDelay old, or at once through its fast lane.
interface IThreatFlags {
    function isAddressEnforced(uint256 chainId, address who) external view returns (bool, uint8);
    function isContractEnforced(address who) external view returns (bool, uint8);
    function isAddressHeld(uint256 chainId, address who) external view returns (bool, uint8);
    function isContractHeld(address who) external view returns (bool, uint8);
}

/// NeuroControl (Neuro's stop switch); only `paused()` is used here.
interface INeuroControl {
    function paused() external view returns (bool);
}

/// A lane says who decides what it attests (NeuroLane: its runner records;
/// HyperlaneLane: its Mailbox). Lanes whose controllers are the same address
/// are one lane as far as independence goes.
interface ILaneInfo {
    function laneController() external view returns (address);
}

/// @title BridgeAirlock: nothing enters ZETAPHY on one bridge's word (stage 3)
/// @notice Defence in depth for incoming assets:
///   1. Several independent "lanes" (Hyperlane, IBC, the Neuro runner lane...)
///      must each attest the SAME transfer. One hacked bridge alone cannot
///      create money.
///   2. Even then the transfer waits in quarantine. During it, vetoers (the
///      Neuro lane by quorum, or a guardian) can stop it.
///   3. Markers: keys governance names (setMarker), typically the bridge
///      monitor's own low-privilege key, can mark an address (trip). A
///      transfer from or to a marked address is not released until governance
///      lifts the mark (untrip). Why an address is marked is decided off-chain
///      by the marker; the airlock keeps no list of what it watches.
///   4. Vaccine: with a ThreatRegistry set, a transfer whose source sender or
///      source contract (on its chain), or whose ZETAPHY recipient (address or
///      code), is flagged by the Neuro runners is not released:
///        - flagged, within the registry's holdDelay (e.g. 10 minutes): not
///          held yet, so a 2-runner quorum alone cannot freeze anyone's
///          transfers at once; governance or a guardian can holdNow(key)
///          meanwhile (the registry's fast lane holds at once too).
///        - held (past holdDelay, fast lane or holdNow), not enforced yet:
///          release reverts with ThreatHeld. It comes out once the flag is
///          cleared (same quorum, or an upheld appeal) or governance protects
///          the key; nothing else releases it.
///        - enforced (past the registry's enforceDelay, or at once through its
///          fast lane): refused, release reverts with ThreatFlagged, as long as
///          the flag stands. The transfer stays, so it still comes out if the
///          flag is cleared or the key protected.
///      For a hold that outlives any flag, the Neuro lane or a guardian vetoes.
///      The coins stay locked in the source chain's LockBox meanwhile: it has no
///      refund path, so a held (or vetoed) transfer is not paid back there.
///      deploy-bridge therefore protects the bridge's own keys and the source
///      LockBox in the registry, so runners cannot hold every transfer at once.
///   Released transfers still pass BridgeGuard's daily limits.
///   Independence: each lane names its controller (laneController(): NeuroLane
///   its runner records, HyperlaneLane its Mailbox; a plain key is its own).
///   independentLanes() counts distinct controllers, and BridgeGuard enables
///   this airlock's route only while it is 2 or more.
contract BridgeAirlock {
    struct Transfer {
        uint64 readyFrom;    // when the threshold was reached; quarantine counts from here
        uint8 attestations;
        bool released;
        bool vetoed;
    }

    IGuardInbound public immutable guard;
    bytes32 public immutable route;     // this airlock's route in BridgeGuard
    address public governance;
    uint8 public threshold;             // distinct lanes that must agree
    uint64 public quarantine;           // seconds a transfer waits after enough lanes agreed
    mapping(address => bool) public isLane;
    address[] private laneList;         // the lanes now on, in no particular order
    uint256 public constant MAX_LANES = 16;
    mapping(address => bool) public isVetoer;
    /// Keys that may mark addresses (trip). See trip(): a marker can only mark.
    mapping(address => bool) public isMarker;
    uint256 public markerCount;         // markers now on
    /// Who marked an address (zero: not marked). A mark counts only while its
    /// marker is still a marker, so removing a stolen marker key lifts all of
    /// its marks at once (see tripped()).
    mapping(address => address) public trippedBy;
    mapping(bytes32 => Transfer) public transfers;
    mapping(bytes32 => mapping(address => bool)) public attestedBy;
    /// By controller (laneControllerOf at attest time): two lanes with one
    /// controller count once, so the threshold means independent lanes.
    mapping(bytes32 => mapping(address => bool)) public attestedByController;
    IThreatFlags public threats;        // zero: no vaccine check

    event LaneSet(address lane, bool on);
    event GovernanceSet(address governance);
    event ThresholdSet(uint8 threshold);
    event QuarantineSet(uint64 quarantine);
    event Untripped(address indexed who);
    event VetoerSet(address who, bool on);
    event MarkerSet(address marker, bool on);
    /// The transfer's details too, so a monitor sees two lanes that disagree
    /// about one source deposit (same chain, contract and nonce; another id).
    event Attested(bytes32 indexed id, address indexed lane, uint8 count, uint256 srcChainId, address srcContract,
        uint256 indexed srcNonce, address sender, address to, uint256 amount);
    event Vetoed(bytes32 indexed id, address indexed by, string reason);
    event Released(bytes32 indexed id, address indexed to, uint256 amount);
    event Tripped(address indexed who, address indexed by);
    event ThreatsSet(address registry);

    error NotGovernance();
    error NotLane();
    error NotVetoer();
    error NotMarker();
    error NotGuardian();
    error Twice();
    error NotReady();
    error Blocked();
    /// what: 1 source sender, 2 source contract, 3 ZETAPHY recipient (enforced flag)
    error ThreatFlagged(uint8 what);
    /// the same, for a held flag that is not enforced yet: held until it is cleared
    error ThreatHeld(uint8 what);

    constructor(IGuardInbound guard_, bytes32 route_, address governance_, uint8 threshold_, uint64 quarantine_) {
        require(threshold_ >= 2, "need 2+ independent lanes");
        guard = guard_;
        route = route_;
        governance = governance_;
        threshold = threshold_;
        quarantine = quarantine_;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setLane(address lane, bool on) external onlyGov {
        if (on && !isLane[lane]) {
            require(lane != address(0) && laneList.length < MAX_LANES, "lane");
            laneList.push(lane);
        } else if (!on && isLane[lane]) {
            for (uint256 i = 0; i < laneList.length; i++) {
                if (laneList[i] == lane) { laneList[i] = laneList[laneList.length - 1]; laneList.pop(); break; }
            }
        }
        isLane[lane] = on;
        emit LaneSet(lane, on);
    }
    function setVetoer(address who, bool on) external onlyGov { isVetoer[who] = on; emit VetoerSet(who, on); }
    /// Names (or removes) a marker: typically the bridge monitor's own key, which
    /// holds no other role. Governance removes a lost or misused marker key here.
    function setMarker(address marker, bool on) external onlyGov {
        if (on != isMarker[marker]) {
            if (on) markerCount += 1;
            else markerCount -= 1;
        }
        isMarker[marker] = on;
        emit MarkerSet(marker, on);
    }
    /// Raising the threshold later does not hold back transfers that already reached the old one.
    function setThreshold(uint8 t) external onlyGov { require(t >= 2, "need 2+"); threshold = t; emit ThresholdSet(t); }
    function setQuarantine(uint64 q) external onlyGov { quarantine = q; emit QuarantineSet(q); }
    function setGovernance(address g) external onlyGov { governance = g; emit GovernanceSet(g); }
    /// The ThreatRegistry whose flags hold transfers (zero turns the check off).
    function setThreats(IThreatFlags r) external onlyGov { threats = r; emit ThreatsSet(address(r)); }
    /// Governance can lift a mark set by mistake.
    function untrip(address who) external onlyGov { delete trippedBy[who]; emit Untripped(who); }

    // ---- emergency: BridgeGuard's guardians act at once, but only to reduce risk ----
    // Governance is meant to be the ZetaphyTimelock (48 h). Adding a lane or a
    // marker, lowering the threshold or the quarantine, lifting a mark, a new
    // registry or governance all wait that delay. These four only make release
    // harder, so a guardian of the guard (a multisig, BridgeGuard.setGuardian)
    // makes them at once. (Removing a marker lifts its marks, as setMarker does:
    // it is how a stolen marker key that marks everyone is stopped.)
    uint64 public constant MAX_QUARANTINE = 30 days;

    function emergencyRemoveLane(address lane) external {
        _guardian();
        if (!isLane[lane]) revert NotLane();
        for (uint256 i = 0; i < laneList.length; i++) {
            if (laneList[i] == lane) { laneList[i] = laneList[laneList.length - 1]; laneList.pop(); break; }
        }
        isLane[lane] = false;
        emit LaneSet(lane, false);
    }

    function emergencyRemoveMarker(address marker) external {
        _guardian();
        if (!isMarker[marker]) revert NotMarker();
        isMarker[marker] = false;
        markerCount -= 1;
        emit MarkerSet(marker, false);
    }

    /// More independent lanes must agree (at most MAX_LANES; above the lane count nothing is released).
    function emergencyRaiseThreshold(uint8 t) external {
        _guardian();
        require(t > threshold && t <= MAX_LANES, "raise only");
        threshold = t;
        emit ThresholdSet(t);
    }

    /// A longer quarantine (at most MAX_QUARANTINE), more time to veto.
    function emergencyRaiseQuarantine(uint64 q) external {
        _guardian();
        require(q > quarantine && q <= MAX_QUARANTINE, "raise only");
        quarantine = q;
        emit QuarantineSet(q);
    }

    /// Governance, or a guardian of the guard (a guard without guardian() has none).
    function _guardian() private view {
        if (msg.sender == governance) return;
        (bool ok, bytes memory ret) = address(guard).staticcall(abi.encodeCall(IGuardInbound.guardian, (msg.sender)));
        if (!ok || ret.length < 32 || !abi.decode(ret, (bool))) revert NotGuardian();
    }

    /// Marked by a marker that is still on. setMarker(m, false) lifts every
    /// mark m made (setting m on again would bring them back).
    function tripped(address who) public view returns (bool) {
        address m = trippedBy[who];
        return m != address(0) && isMarker[m];
    }

    /// The lanes now on.
    function lanes() external view returns (address[] memory) { return laneList; }
    function laneCount() external view returns (uint256) { return laneList.length; }

    /// Who decides what a lane attests: its laneController(), or the lane itself
    /// (a key, or a contract that does not say).
    function laneControllerOf(address lane) public view returns (address) {
        if (lane.code.length == 0) return lane;
        try ILaneInfo(lane).laneController() returns (address c) { return c == address(0) ? lane : c; } catch { return lane; }
    }

    /// Lanes with distinct controllers. BridgeGuard will not enable this
    /// airlock's route while it is below 2: one controller behind two lane
    /// contracts is still one bridge's word.
    function independentLanes() external view returns (uint256 n) {
        uint256 len = laneList.length;
        address[] memory seen = new address[](len);
        for (uint256 i = 0; i < len; i++) {
            address c = laneControllerOf(laneList[i]);
            bool dup = false;
            for (uint256 j = 0; j < n; j++) if (seen[j] == c) { dup = true; break; }
            if (!dup) seen[n++] = c;
        }
    }

    /// The id every lane computes for one transfer seen on the source chain:
    /// the source contract's own running number, not a tx hash or log
    /// position, which can change if the source chain reorganises.
    function transferId(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount)
        public pure returns (bytes32)
    {
        return keccak256(abi.encode(srcChainId, srcContract, srcNonce, sender, to, amount));
    }

    function attest(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external {
        if (!isLane[msg.sender]) revert NotLane();
        bytes32 id = transferId(srcChainId, srcContract, srcNonce, sender, to, amount);
        if (attestedBy[id][msg.sender]) revert Twice();
        attestedBy[id][msg.sender] = true;
        Transfer storage t = transfers[id];
        address c = laneControllerOf(msg.sender);
        if (!attestedByController[id][c]) {
            attestedByController[id][c] = true;
            t.attestations += 1;
        }
        if (t.readyFrom == 0 && t.attestations >= threshold) t.readyFrom = uint64(block.timestamp);
        emit Attested(id, msg.sender, t.attestations, srcChainId, srcContract, srcNonce, sender, to, amount);
    }

    function veto(bytes32 id, string calldata reason) external {
        if (!isVetoer[msg.sender]) revert NotVetoer();
        Transfer storage t = transfers[id];
        if (t.released) revert Blocked();
        t.vetoed = true;
        emit Vetoed(id, msg.sender, reason);
    }

    /// A marker marks `who`: release() then refuses (Blocked) every transfer
    /// whose source sender or ZETAPHY recipient is `who`, until governance
    /// untrips it. That is all a marker can do: it cannot attest, veto,
    /// release, mint, pause or move any funds, and a mark loses nothing (the
    /// transfer stays and comes out once the mark is lifted). So a stolen or
    /// misused marker key can at worst delay some addresses' transfers until
    /// governance removes the marker (setMarker), which lifts all its marks.
    function trip(address who) external {
        if (!isMarker[msg.sender]) revert NotMarker();
        trippedBy[who] = msg.sender;
        emit Tripped(who, msg.sender);
    }

    /// Anyone may release a transfer that passed every check.
    function release(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external {
        bytes32 id = transferId(srcChainId, srcContract, srcNonce, sender, to, amount);
        Transfer storage t = transfers[id];
        if (t.released || t.vetoed || tripped(sender) || tripped(to)) revert Blocked();
        if (t.attestations < threshold || t.readyFrom == 0 || block.timestamp < t.readyFrom + quarantine) revert NotReady();
        uint8 what = flaggedParty(srcChainId, srcContract, sender, to);
        if (what != 0) revert ThreatFlagged(what);
        what = heldParty(srcChainId, srcContract, sender, to);
        if (what != 0) revert ThreatHeld(what);
        t.released = true;
        guard.inbound(route, to, amount);
        emit Released(id, to, amount);
    }

    /// 0 when no party of this transfer has an enforced flag, else which one
    /// has (see ThreatFlagged). NeuroLane watchers ask this before they attest.
    function flaggedParty(uint256 srcChainId, address srcContract, address sender, address to) public view returns (uint8) {
        return _party(srcChainId, srcContract, sender, to, true);
    }

    /// 0 when no party of this transfer is held, else which one is (the
    /// registry's is*Held views: past holdDelay, fast lane or holdNow). A
    /// transfer with a held party is not released; NeuroLane watchers ask this
    /// before they release.
    function heldParty(uint256 srcChainId, address srcContract, address sender, address to) public view returns (uint8) {
        return _party(srcChainId, srcContract, sender, to, false);
    }

    function _party(uint256 srcChainId, address srcContract, address sender, address to, bool enforced) private view returns (uint8) {
        IThreatFlags r = threats;
        if (address(r) == address(0)) return 0;
        bool f;
        (f, ) = enforced ? r.isAddressEnforced(srcChainId, sender) : r.isAddressHeld(srcChainId, sender);
        if (f) return 1;
        (f, ) = enforced ? r.isAddressEnforced(srcChainId, srcContract) : r.isAddressHeld(srcChainId, srcContract);
        if (f) return 2;
        (f, ) = enforced ? r.isContractEnforced(to) : r.isContractHeld(to);
        if (f) return 3;
        return 0;
    }

    function status(bytes32 id) external view returns (uint8 attestations, bool released, bool vetoed, uint64 readyAt) {
        Transfer storage t = transfers[id];
        return (t.attestations, t.released, t.vetoed, t.readyFrom == 0 ? 0 : t.readyFrom + quarantine);
    }
}

/// @title NeuroLane: Neuro runners as one of the airlock's bridges
/// @notice Runners watch the source chain's LockBox and each attest the
///         transfers they see. When `quorum` distinct proven runners attest
///         the same transfer, this lane attests it to the airlock. Runners
///         can also vote to veto a transfer still in quarantine.
///         While Neuro is paused (NeuroControl, if set) nothing is attested;
///         vetoes still work, since holding money back is always safe.
contract NeuroLane {
    IRunnerRecords public immutable runners;
    BridgeAirlock public immutable airlock;
    uint8 public immutable quorum;
    uint32 public immutable minAgreed;
    INeuroControl public immutable control; // zero: no pause check

    mapping(bytes32 => uint8) public votes;
    mapping(bytes32 => mapping(address => bool)) public votedBy;
    mapping(bytes32 => bool) public done;

    event RunnerAttested(bytes32 indexed id, address indexed runner, uint8 votes);

    /// The runner records decide what this lane attests (BridgeAirlock.independentLanes).
    function laneController() external view returns (address) { return address(runners); }
    event RunnerVetoVote(bytes32 indexed id, address indexed runner, uint8 votes);

    error NotRunner();
    error Twice();
    error NeuroPaused();

    constructor(IRunnerRecords runners_, BridgeAirlock airlock_, uint8 quorum_, uint32 minAgreed_, INeuroControl control_) {
        require(quorum_ >= 2, "quorum");
        runners = runners_;
        airlock = airlock_;
        quorum = quorum_;
        minAgreed = minAgreed_;
        control = control_;
    }

    function _runner() private view {
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(msg.sender);
        if (!active || agreed < minAgreed || rejected > agreed) revert NotRunner();
    }

    function attest(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external {
        _runner();
        if (address(control) != address(0) && control.paused()) revert NeuroPaused();
        bytes32 id = airlock.transferId(srcChainId, srcContract, srcNonce, sender, to, amount);
        bytes32 key = keccak256(abi.encode("attest", id));
        if (votedBy[key][msg.sender] || done[key]) revert Twice();
        votedBy[key][msg.sender] = true;
        uint8 v = ++votes[key];
        emit RunnerAttested(id, msg.sender, v);
        if (v >= quorum) {
            done[key] = true;
            airlock.attest(srcChainId, srcContract, srcNonce, sender, to, amount);
        }
    }

    function voteVeto(bytes32 id, string calldata reason) external {
        _runner();
        bytes32 key = keccak256(abi.encode("veto", id));
        if (votedBy[key][msg.sender] || done[key]) revert Twice();
        votedBy[key][msg.sender] = true;
        uint8 v = ++votes[key];
        emit RunnerVetoVote(id, msg.sender, v);
        if (v >= quorum) {
            done[key] = true;
            airlock.veto(id, reason);
        }
    }
}

/// @title LockBox: the source-chain side of the Neuro lane (test / testnet)
/// @notice Locks native coin and emits what the lanes need to attest. Lanes
///         attest (chainid, this contract, nonce, sender, to, amount).
contract LockBox {
    uint256 public nonce;
    event Locked(uint256 indexed nonce, address indexed sender, address indexed to, uint256 amount);

    function lock(address to) external payable {
        require(msg.value > 0 && to != address(0), "lock");
        emit Locked(nonce++, msg.sender, to, msg.value);
    }
}

contracts/BridgeGuard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// ThreatRegistry's hold view for code on ZETAPHY (Reason as its uint8 value):
/// true once a flag on its address or code is the registry's holdDelay old, or at
/// once through the registry's fast lane or a guardian's holdNow.
interface IContractThreats {
    function isContractHeld(address who) external view returns (bool, uint8);
}

/// BridgeAirlock's count of lanes with distinct controllers.
interface IIndependentLanes {
    function independentLanes() external view returns (uint256);
}

/// @title BridgedToken: a token that exists on ZETAPHY only through a bridge
/// @notice Only its BridgeGuard can mint (assets arriving) or burn (leaving).
contract BridgedToken {
    string public name;
    string public symbol;
    uint8 public immutable decimals;
    address public immutable guard;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor(string memory n, string memory s, uint8 d, address guard_) {
        name = n; symbol = s; decimals = d; guard = guard_;
    }

    modifier onlyGuard() { require(msg.sender == guard, "only guard"); _; }

    function mint(address to, uint256 v) external onlyGuard { totalSupply += v; balanceOf[to] += v; emit Transfer(address(0), to, v); }
    function burn(address from, uint256 v) external onlyGuard {
        require(balanceOf[from] >= v, "balance");
        balanceOf[from] -= v; totalSupply -= v; emit Transfer(from, address(0), v);
    }
    function approve(address s, uint256 v) external returns (bool) { allowance[msg.sender][s] = v; emit Approval(msg.sender, s, v); return true; }
    function transfer(address to, uint256 v) external returns (bool) { _move(msg.sender, to, v); return true; }
    function transferFrom(address f, address to, uint256 v) external returns (bool) {
        uint256 a = allowance[f][msg.sender];
        if (a != type(uint256).max) { require(a >= v, "allowance"); allowance[f][msg.sender] = a - v; }
        _move(f, to, v); return true;
    }
    function _move(address f, address to, uint256 v) private {
        require(to != address(0) && balanceOf[f] >= v, "transfer");
        balanceOf[f] -= v; balanceOf[to] += v; emit Transfer(f, to, v);
    }
}

/// @title BridgeGuard: limits and a stop button for every bridge route (stage 3)
/// @notice A bridge adapter (Hyperlane warp route, IBC hook, ...) never mints
///         or burns directly: it asks this guard, which enforces
///           - a daily limit per route and direction, so a hacked bridge can
///             lose at most one day's limit, not everything;
///           - a pause that only guardians can pull and only governance can
///             release. Pausing stops the bridges, never the chain.
///           - vaccine (with a ThreatRegistry set): no coins to, or out of, an
///             address or contract the registry holds (is*Held: a flag that is
///             holdDelay old, e.g. 10 minutes, or held at once by the fast lane or
///             a guardian's holdNow; two runners alone cannot freeze anyone at
///             once). This is a hold, not a loss:
///               - inbound: the mint is QUEUED, not reverted (InboundHeld, an id
///                 in `held`). The adapter's message is delivered, so nothing
///                 depends on an adapter retrying. Anyone calls releaseHeld(id)
///                 once the hold ends (the flag cleared, or governance protects
///                 the key); it then passes the pause, the route (still enabled)
///                 and the route's daily limit like any inbound. Governance can
///                 dropHeld(id) a queued mint (e.g. from a hacked adapter).
///               - outbound: the call reverts (the burn simply did not happen;
///                 the holder keeps the coins).
///             The adapter itself is NOT checked: governance chose it and can
///             disable its route; a runner flag on its code hash or address must
///             not be able to freeze a whole route.
///         Opening gates (a route stays closed until they hold):
///           - an audit on record: setAudit(https url, sha256 of the report)
///             before any route can be enabled;
///           - the route's adapter is a BridgeAirlock with at least 2 lanes
///             whose controllers differ (independentLanes() >= 2);
///           - a hard cap, maxDailyLimit, over every route's daily limit and over all routes together per day. It
///             starts at 1,000 whole tokens (createToken), is lowered at once,
///             and is raised only by governance, at most x2 per step, each step
///             7 days after it was proposed: caps grow gradually and in public.
///         Governance should be the ZetaphyTimelock (proposers: the chain's gov
///         module or a multisig). Guardians act at once, but only to reduce risk:
///         pause, lowerMaxDailyLimit, cancelMaxDailyLimit, disableRoute.
contract BridgeGuard {
    struct Route {
        address adapter;      // the only caller allowed for this route
        uint128 dailyLimit;   // per direction, in token units
        uint128 inToday;
        uint128 outToday;
        uint64 day;
        bool enabled;
    }

    BridgedToken public token;
    address public governance;
    mapping(address => bool) public guardian;
    bool public paused;
    mapping(bytes32 => Route) public routes;
    IContractThreats public threats; // zero: no vaccine check
    address[] private guardianList;  // everyone ever made a guardian (guardians() filters the current ones)

    /// The audit the bridge opened on: where to read it and the sha256 of the report.
    string public auditUrl;
    bytes32 public auditSha256;
    /// Hard cap over every route's daily limit (token units).
    uint128 public maxDailyLimit;
    uint128 public pendingMaxDailyLimit;
    uint64 public pendingMaxAt;      // when the pending raise may be applied (0: none)
    uint64 public constant CAP_DELAY = 7 days;
    uint128 public constant STARTER_UNITS = 1000; // whole tokens: the cap at createToken
    /// Every route together, per direction and day: the hard cap binds the
    /// guard, so more routes cannot multiply it.
    uint128 public totalInToday;
    uint128 public totalOutToday;
    uint64 public totalDay;

    /// Inbound mints held by the vaccine, waiting for releaseHeld.
    struct HeldMint {
        bytes32 route;
        address to;
        uint256 amount;
        bool done;       // released or dropped
    }
    HeldMint[] public held;

    event RouteSet(bytes32 indexed id, address adapter, uint128 dailyLimit, bool enabled);
    event GovernanceSet(address governance);
    event AuditSet(string url, bytes32 sha256);
    event MaxDailyLimitProposed(uint128 value, uint64 at);
    event MaxDailyLimitSet(uint128 value);
    event MaxDailyLimitCancelled();
    event GuardianSet(address indexed who, bool allowed);
    event Paused(address indexed by);
    event Unpaused();
    event Inbound(bytes32 indexed route, address indexed to, uint256 amount);
    event Outbound(bytes32 indexed route, address indexed from, uint256 amount);
    event ThreatsSet(address registry);
    event InboundHeld(uint256 indexed id, bytes32 indexed route, address indexed to, uint256 amount);
    event HeldReleased(uint256 indexed id, address indexed to, uint256 amount);
    event HeldDropped(uint256 indexed id);

    error NotGovernance();
    error NotGuardian();
    error NotAdapter();
    error BridgePaused();
    error OverLimit(uint256 remaining);
    error FlaggedContract(address who);
    error NoHeld();
    error AuditMissing();
    error NeedLanes(uint256 independent);
    error OverCap(uint128 cap);
    error CapStep(uint128 most);
    error TooEarly(uint64 at);
    error NoPending();

    constructor(address governance_) {
        governance = governance_;
    }

    /// One-time: the guard deploys and owns its token.
    function createToken(string calldata n, string calldata s, uint8 d) external returns (BridgedToken) {
        if (msg.sender != governance) revert NotGovernance();
        require(address(token) == address(0), "token exists");
        require(d <= 30, "decimals");
        token = new BridgedToken(n, s, d, address(this));
        maxDailyLimit = uint128(uint256(STARTER_UNITS) * (uint256(10) ** d));
        emit MaxDailyLimitSet(maxDailyLimit);
        return token;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setGovernance(address g) external onlyGov { governance = g; emit GovernanceSet(g); }
    function setGuardian(address who, bool allowed) external onlyGov {
        if (allowed && !guardian[who]) {
            bool known = false;
            for (uint256 i = 0; i < guardianList.length; i++) if (guardianList[i] == who) { known = true; break; }
            if (!known) { require(guardianList.length < 32, "guardians"); guardianList.push(who); }
        }
        guardian[who] = allowed;
        emit GuardianSet(who, allowed);
    }

    /// The current guardians.
    function guardians() external view returns (address[] memory out) {
        uint256 n = 0;
        for (uint256 i = 0; i < guardianList.length; i++) if (guardian[guardianList[i]]) n++;
        out = new address[](n);
        n = 0;
        for (uint256 i = 0; i < guardianList.length; i++) if (guardian[guardianList[i]]) out[n++] = guardianList[i];
    }

    /// The audit report the bridge opens on (an https url and the report's sha256).
    function setAudit(string calldata url, bytes32 sha) external onlyGov {
        bytes memory u = bytes(url);
        require(sha != bytes32(0) && u.length > 8 && u.length <= 200 && u[0] == "h" && u[1] == "t" && u[2] == "t" && u[3] == "p"
            && u[4] == "s" && u[5] == ":" && u[6] == "/" && u[7] == "/", "audit: https url and sha256");
        auditUrl = url;
        auditSha256 = sha;
        emit AuditSet(url, sha);
    }

    /// Lowering the cap applies at once (and cancels a pending raise); a raise
    /// (at most x2 of the cap) waits CAP_DELAY, then anyone applies it.
    function proposeMaxDailyLimit(uint128 v) external onlyGov {
        if (v <= maxDailyLimit) {
            maxDailyLimit = v;
            pendingMaxAt = 0;
            pendingMaxDailyLimit = 0;
            emit MaxDailyLimitSet(v);
            return;
        }
        uint256 most = uint256(maxDailyLimit) * 2;
        if (v > most) revert CapStep(uint128(most));
        pendingMaxDailyLimit = v;
        pendingMaxAt = uint64(block.timestamp) + CAP_DELAY;
        emit MaxDailyLimitProposed(v, pendingMaxAt);
    }

    function applyMaxDailyLimit() external {
        uint64 at = pendingMaxAt;
        if (at == 0) revert NoPending();
        if (block.timestamp < at) revert TooEarly(at);
        maxDailyLimit = pendingMaxDailyLimit;
        pendingMaxAt = 0;
        pendingMaxDailyLimit = 0;
        emit MaxDailyLimitSet(maxDailyLimit);
    }

    /// Governance or a guardian: drop a pending raise (reducing risk never waits).
    function cancelMaxDailyLimit() external {
        _govOrGuardian();
        pendingMaxAt = 0;
        pendingMaxDailyLimit = 0;
        emit MaxDailyLimitCancelled();
    }

    // ---- emergency: guardians act at once, but only to reduce risk ----
    // With governance behind a timelock (ZetaphyTimelock, 48 h), everything that
    // raises risk or changes rules (enable a route, raise a cap, unpause, new
    // guardians, audit, registry, governance) waits the delay. These calls only
    // shrink what can cross, so a guardian (a multisig) makes them at once.

    /// Lower the hard cap (never raise it) and drop a pending raise.
    function lowerMaxDailyLimit(uint128 v) external {
        _govOrGuardian();
        if (v >= maxDailyLimit) revert CapStep(maxDailyLimit);
        maxDailyLimit = v;
        pendingMaxAt = 0;
        pendingMaxDailyLimit = 0;
        emit MaxDailyLimitSet(v);
    }

    /// Close a route (its adapter and limit are kept; enabling it again is governance's).
    function disableRoute(bytes32 id) external {
        _govOrGuardian();
        Route storage r = routes[id];
        r.enabled = false;
        emit RouteSet(id, r.adapter, r.dailyLimit, false);
    }

    function _govOrGuardian() private view {
        if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian();
    }
    /// The ThreatRegistry whose flags refuse coins (zero turns the check off).
    function setThreats(IContractThreats r) external onlyGov { threats = r; emit ThreatsSet(address(r)); }

    /// Enabling needs the audit on record, a daily limit within the hard cap and
    /// an adapter that is a BridgeAirlock with 2+ independent lanes. Disabling (or
    /// setting a closed route up) needs none of them: closing always works.
    function setRoute(bytes32 id, address adapter, uint128 dailyLimit, bool enabled) external onlyGov {
        if (enabled) {
            if (dailyLimit > maxDailyLimit) revert OverCap(maxDailyLimit);
            if (auditSha256 == bytes32(0)) revert AuditMissing();
            uint256 n = _independentLanes(adapter);
            if (n < 2) revert NeedLanes(n);
        }
        Route storage r = routes[id];
        r.adapter = adapter;
        r.dailyLimit = dailyLimit;
        r.enabled = enabled;
        emit RouteSet(id, adapter, dailyLimit, enabled);
    }

    /// Any guardian (or governance) can stop all bridges at once.
    function pause() external {
        if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian();
        paused = true;
        emit Paused(msg.sender);
    }

    /// Restarting needs governance: a stolen guardian key can only stop things.
    function unpause() external onlyGov {
        paused = false;
        emit Unpaused();
    }

    /// A held recipient: the mint is queued (InboundHeld), not reverted, and
    /// counts against the daily limit only when it is released.
    function inbound(bytes32 id, address to, uint256 amount) external {
        Route storage r = _use(id, amount, true);
        if (_isHeld(to)) {
            held.push(HeldMint(id, to, amount, false));
            emit InboundHeld(held.length - 1, id, to, amount);
            return;
        }
        _total(amount, true);
        r.inToday += uint128(amount);
        token.mint(to, amount);
        emit Inbound(id, to, amount);
    }

    /// Anyone: mint a queued inbound once its recipient is no longer held.
    /// Passes the pause, the route being enabled and its daily limit, as inbound does.
    function releaseHeld(uint256 hid) external {
        if (hid >= held.length || held[hid].done) revert NoHeld();
        HeldMint storage h = held[hid];
        if (paused) revert BridgePaused();
        Route storage r = routes[h.route];
        if (!r.enabled) revert NotAdapter();
        _clean(h.to);
        uint64 today = uint64(block.timestamp / 1 days);
        if (r.day != today) { r.day = today; r.inToday = 0; r.outToday = 0; }
        uint128 lim = _limit(r);
        if (r.inToday + h.amount > lim) revert OverLimit(lim > r.inToday ? lim - r.inToday : 0);
        _total(h.amount, true);
        h.done = true;
        r.inToday += uint128(h.amount);
        token.mint(h.to, h.amount);
        emit HeldReleased(hid, h.to, h.amount);
        emit Inbound(h.route, h.to, h.amount);
    }

    /// Governance drops a queued mint (e.g. one a hacked adapter sent).
    function dropHeld(uint256 hid) external onlyGov {
        if (hid >= held.length || held[hid].done) revert NoHeld();
        held[hid].done = true;
        emit HeldDropped(hid);
    }

    function heldCount() external view returns (uint256) {
        return held.length;
    }

    function outbound(bytes32 id, address from, uint256 amount) external {
        Route storage r = _use(id, amount, false);
        _clean(from);
        _total(amount, false);
        r.outToday += uint128(amount);
        token.burn(from, amount);
        emit Outbound(id, from, amount);
    }

    function remaining(bytes32 id) external view returns (uint256 inLeft, uint256 outLeft) {
        Route storage r = routes[id];
        bool fresh = r.day != uint64(block.timestamp / 1 days);
        uint128 lim = _limit(r);
        uint128 i = fresh ? 0 : r.inToday;
        uint128 o = fresh ? 0 : r.outToday;
        inLeft = lim > i ? lim - i : 0;
        outLeft = lim > o ? lim - o : 0;
    }

    /// A route's daily limit, never above the hard cap.
    function _limit(Route storage r) private view returns (uint128) {
        return r.dailyLimit < maxDailyLimit ? r.dailyLimit : maxDailyLimit;
    }

    /// The hard cap over all routes together (per direction, per day).
    function _total(uint256 amount, bool isIn) private {
        uint64 today = uint64(block.timestamp / 1 days);
        if (totalDay != today) { totalDay = today; totalInToday = 0; totalOutToday = 0; }
        uint256 used = isIn ? totalInToday : totalOutToday;
        uint256 cap = maxDailyLimit;
        if (used + amount > cap) revert OverLimit(cap > used ? cap - used : 0);
        if (isIn) totalInToday = uint128(used + amount); else totalOutToday = uint128(used + amount);
    }

    function _independentLanes(address adapter) private view returns (uint256) {
        if (adapter.code.length == 0) return 0;
        (bool ok, bytes memory ret) = adapter.staticcall(abi.encodeCall(IIndependentLanes.independentLanes, ()));
        if (!ok || ret.length < 32) return 0;
        return abi.decode(ret, (uint256));
    }

    /// Vaccine: holds back a party (the coins' owner) that the registry holds.
    function _clean(address who) private view {
        if (_isHeld(who)) revert FlaggedContract(who);
    }

    function _isHeld(address who) private view returns (bool f) {
        IContractThreats t = threats;
        if (address(t) == address(0)) return false;
        (f, ) = t.isContractHeld(who);
    }

    function _use(bytes32 id, uint256 amount, bool isIn) private returns (Route storage r) {
        if (paused) revert BridgePaused();
        r = routes[id];
        if (!r.enabled || msg.sender != r.adapter) revert NotAdapter();
        uint64 today = uint64(block.timestamp / 1 days);
        if (r.day != today) { r.day = today; r.inToday = 0; r.outToday = 0; }
        uint256 used = isIn ? r.inToday : r.outToday;
        uint256 lim = _limit(r);
        if (used + amount > lim) revert OverLimit(lim > used ? lim - used : 0);
    }
}

contracts/ComputeMarket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IRunnersView {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

/// @title ComputeMarket: pay node runners in ZETAPHY for AI work (stage 4)
/// @notice Model output (tier 2+) is not deterministic, so it cannot be
///         settled by 2-of-3 agreement like Neuro tier 1. Instead: escrow.
///         The requester pays up front; a runner with a NeuroJobs track
///         record takes the task and delivers a result (hash + URI); the
///         requester accepts or rejects within REVIEW. Silence pays the
///         runner. Both sides' reject counts are public, so runners can avoid
///         requesters who reject everything, and requesters can avoid runners
///         who deliver junk.
contract ComputeMarket {
    uint64 public constant REVIEW = 1 days;

    enum Status { None, Open, Taken, Delivered, Paid, Refunded }

    struct Task {
        address requester;
        address runner;
        Status status;
        uint64 deadline;     // delivery due
        uint64 deliveredAt;
        bytes32 model;       // e.g. "llama-3.1-8b-instruct-q4"
        bytes32 inputHash;
        bytes32 resultHash;
        uint256 price;
        string inputURI;
        string resultURI;
    }

    IRunnersView public immutable runners;
    uint32 public immutable minAgreed;
    Task[] internal tasks;
    mapping(address => uint256) public credit;
    mapping(address => uint32) public runnerDone;
    mapping(address => uint32) public runnerRejected;
    mapping(address => uint32) public requesterRejections;

    event Requested(uint256 indexed id, bytes32 indexed model, uint256 price, uint64 deadline);
    event Taken(uint256 indexed id, address indexed runner);
    event Delivered(uint256 indexed id, bytes32 resultHash, string resultURI);
    event Settled(uint256 indexed id, Status status);

    error BadValue();
    error BadState();
    error NotAllowed();
    error TooEarly();
    error Nothing();

    constructor(IRunnersView runners_, uint32 minAgreed_) {
        runners = runners_;
        minAgreed = minAgreed_;
    }

    function request(bytes32 model, bytes32 inputHash, string calldata inputURI, uint64 seconds_) external payable returns (uint256 id) {
        if (msg.value == 0 || model == bytes32(0) || seconds_ == 0 || seconds_ > 7 days || bytes(inputURI).length > 256) revert BadValue();
        id = tasks.length;
        Task storage t = tasks.push();
        t.requester = msg.sender;
        t.status = Status.Open;
        t.deadline = uint64(block.timestamp) + seconds_;
        t.model = model;
        t.inputHash = inputHash;
        t.inputURI = inputURI;
        t.price = msg.value;
        emit Requested(id, model, msg.value, t.deadline);
    }

    function take(uint256 id) external {
        Task storage t = _task(id, Status.Open);
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(msg.sender);
        if (!active || agreed < minAgreed || rejected > agreed || msg.sender == t.requester) revert NotAllowed();
        if (block.timestamp >= t.deadline) revert BadState();
        t.runner = msg.sender;
        t.status = Status.Taken;
        emit Taken(id, msg.sender);
    }

    function deliver(uint256 id, bytes32 resultHash, string calldata resultURI) external {
        Task storage t = _task(id, Status.Taken);
        if (msg.sender != t.runner) revert NotAllowed();
        if (block.timestamp > t.deadline || resultHash == bytes32(0) || bytes(resultURI).length > 256) revert BadValue();
        t.resultHash = resultHash;
        t.resultURI = resultURI;
        t.deliveredAt = uint64(block.timestamp);
        t.status = Status.Delivered;
        emit Delivered(id, resultHash, resultURI);
    }

    function accept(uint256 id) external {
        Task storage t = _task(id, Status.Delivered);
        if (msg.sender != t.requester) revert NotAllowed();
        _pay(id, t);
    }

    function reject(uint256 id) external {
        Task storage t = _task(id, Status.Delivered);
        if (msg.sender != t.requester) revert NotAllowed();
        if (block.timestamp > t.deliveredAt + REVIEW) revert BadState();
        runnerRejected[t.runner] += 1;
        requesterRejections[t.requester] += 1;
        _refund(id, t);
    }

    /// The runner is paid once the review window passes without a rejection.
    function claim(uint256 id) external {
        Task storage t = _task(id, Status.Delivered);
        if (block.timestamp <= t.deliveredAt + REVIEW) revert TooEarly();
        _pay(id, t);
    }

    /// Requester gets the money back if nobody took the task, or nothing was delivered in time.
    function cancel(uint256 id) external {
        if (id >= tasks.length) revert BadState();
        Task storage t = tasks[id];
        if (msg.sender != t.requester) revert NotAllowed();
        bool open = t.status == Status.Open;
        bool late = t.status == Status.Taken && block.timestamp > t.deadline;
        if (!open && !late) revert BadState();
        _refund(id, t);
    }

    function withdraw() external {
        uint256 a = credit[msg.sender];
        if (a == 0) revert Nothing();
        credit[msg.sender] = 0;
        (bool ok,) = msg.sender.call{value: a}("");
        require(ok, "transfer failed");
    }

    function taskCount() external view returns (uint256) { return tasks.length; }

    function getTask(uint256 id) external view returns (Task memory) {
        if (id >= tasks.length) revert BadState();
        return tasks[id];
    }

    function _task(uint256 id, Status want) private view returns (Task storage t) {
        if (id >= tasks.length) revert BadState();
        t = tasks[id];
        if (t.status != want) revert BadState();
    }

    function _pay(uint256 id, Task storage t) private {
        t.status = Status.Paid;
        credit[t.runner] += t.price;
        runnerDone[t.runner] += 1;
        emit Settled(id, Status.Paid);
    }

    function _refund(uint256 id, Task storage t) private {
        t.status = Status.Refunded;
        credit[t.requester] += t.price;
        emit Settled(id, Status.Refunded);
    }
}

contracts/HyperlaneLane.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// Minimal local copies of Hyperlane v3 interfaces (no Hyperlane package offline).
// Checked against hyperlane-xyz/hyperlane-monorepo at commit
// bc8cfcec461930ec005590bc838871f903a297a1 (main, 2026-10-21):
//   solidity/contracts/interfaces/IMailbox.sol             dispatch / quoteDispatch / localDomain
//   solidity/contracts/interfaces/IMessageRecipient.sol    handle(uint32, bytes32, bytes) payable
//   solidity/contracts/interfaces/IInterchainSecurityModule.sol  moduleType / verify, and
//     ISpecifiesInterchainSecurityModule.interchainSecurityModule()
// The Mailbox calls recipient.handle{value: msg.value}(origin, sender, body) after
// its ISM (the recipient's interchainSecurityModule(), or the Mailbox default when
// that is zero) verified the message.

interface IHyperlaneMailbox {
    function localDomain() external view returns (uint32);
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external view returns (uint256 fee);
}

interface IInterchainSecurityModule {
    function moduleType() external view returns (uint8);
    function verify(bytes calldata metadata, bytes calldata message) external returns (bool);
}

interface IMessageRecipient {
    function handle(uint32 origin, bytes32 sender, bytes calldata message) external payable;
}

/// BridgeAirlock as a lane sees it.
interface IAirlockLane {
    function attest(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external;
    function transferId(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external pure returns (bytes32);
}

/// @title HyperlaneLane: Hyperlane as one of BridgeAirlock's lanes (ZETAPHY side)
/// @notice Independent of NeuroLane: what it attests is decided by Hyperlane's
///         Mailbox and the ISM (validator set) that secures it, not by Neuro
///         runners. It accepts a message only
///           - from the configured Mailbox (msg.sender),
///           - from the configured origin domain and origin sender (the source
///             chain's HyperlaneLockBox, or a router speaking for it),
///           - describing a deposit of the configured source chain and contract;
///         and each transfer once. It then attests to the airlock exactly the
///         fields NeuroLane attests for the same deposit, so both lanes produce
///         the same transfer id: (srcChainId, srcContract, srcNonce, sender, to, amount).
///         Body: abi.encode(uint256 srcChainId, address srcContract, uint256 srcNonce,
///         address sender, address to, uint256 amount), 192 bytes.
///         Governance (a multisig) sets the config and an optional custom ISM;
///         until the source is configured every message is refused.
contract HyperlaneLane is IMessageRecipient {
    IAirlockLane public immutable airlock;
    address public governance;
    address public mailbox;
    uint32 public originDomain;
    bytes32 public originSender;
    uint256 public srcChainId;
    address public srcContract;
    /// Hyperlane reads this (ISpecifiesInterchainSecurityModule); zero = the Mailbox's default ISM.
    IInterchainSecurityModule public interchainSecurityModule;
    mapping(bytes32 => bool) public delivered;   // by transfer id: replay protection

    event ConfigSet(address mailbox, uint32 originDomain, bytes32 originSender, uint256 srcChainId, address srcContract);
    event IsmSet(address ism);
    event GovernanceSet(address governance);
    event Delivered(bytes32 indexed id, uint256 indexed srcNonce, address sender, address to, uint256 amount);

    error NotGovernance();
    error NotMailbox();
    error WrongOrigin(uint32 origin);
    error WrongSender(bytes32 sender);
    error WrongSource();
    error BadBody();
    error Replay(bytes32 id);
    error NoValue();

    constructor(IAirlockLane airlock_, address governance_, address mailbox_, uint32 originDomain_, bytes32 originSender_,
        uint256 srcChainId_, address srcContract_, IInterchainSecurityModule ism_)
    {
        require(address(airlock_) != address(0) && governance_ != address(0) && mailbox_ != address(0), "config");
        airlock = airlock_;
        governance = governance_;
        _config(mailbox_, originDomain_, originSender_, srcChainId_, srcContract_);
        interchainSecurityModule = ism_;
        emit IsmSet(address(ism_));
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    /// The Mailbox decides what this lane attests (BridgeAirlock.independentLanes).
    function laneController() external view returns (address) { return mailbox; }

    function setConfig(address mailbox_, uint32 originDomain_, bytes32 originSender_, uint256 srcChainId_, address srcContract_) external onlyGov {
        require(mailbox_ != address(0), "mailbox");
        _config(mailbox_, originDomain_, originSender_, srcChainId_, srcContract_);
    }

    function setInterchainSecurityModule(IInterchainSecurityModule ism) external onlyGov {
        interchainSecurityModule = ism;
        emit IsmSet(address(ism));
    }

    function setGovernance(address g) external onlyGov {
        require(g != address(0), "governance");
        governance = g;
        emit GovernanceSet(g);
    }

    function handle(uint32 origin, bytes32 sender, bytes calldata body) external payable {
        if (msg.sender != mailbox) revert NotMailbox();
        if (msg.value != 0) revert NoValue();
        if (origin != originDomain) revert WrongOrigin(origin);
        if (sender != originSender || sender == bytes32(0)) revert WrongSender(sender);
        if (body.length != 192) revert BadBody();
        (uint256 chain, address src, uint256 nonce, address from, address to, uint256 amount) =
            abi.decode(body, (uint256, address, uint256, address, address, uint256));
        if (chain != srcChainId || src != srcContract || src == address(0)) revert WrongSource();
        bytes32 id = airlock.transferId(chain, src, nonce, from, to, amount);
        if (delivered[id]) revert Replay(id);
        delivered[id] = true;
        emit Delivered(id, nonce, from, to, amount);
        airlock.attest(chain, src, nonce, from, to, amount);
    }

    function _config(address mailbox_, uint32 originDomain_, bytes32 originSender_, uint256 srcChainId_, address srcContract_) private {
        mailbox = mailbox_;
        originDomain = originDomain_;
        originSender = originSender_;
        srcChainId = srcChainId_;
        srcContract = srcContract_;
        emit ConfigSet(mailbox_, originDomain_, originSender_, srcChainId_, srcContract_);
    }
}

/// @title HyperlaneLockBox: the source-chain side, for both lanes at once
/// @notice Locks native coin, emits LockBox's `Locked` event (the Neuro runners
///         watch it, unchanged: `zetaphy bridge watch --lockbox <this>`) and
///         dispatches the same transfer through the Hyperlane Mailbox to the
///         HyperlaneLane on ZETAPHY. msg.value = amount + the Mailbox fee
///         (quoteLock). Like LockBox it has no refund path: a vetoed or held
///         transfer stays locked here.
contract HyperlaneLockBox {
    IHyperlaneMailbox public immutable mailbox;
    uint32 public immutable destinationDomain;
    bytes32 public immutable recipient;      // HyperlaneLane on ZETAPHY
    uint256 public nonce;

    event Locked(uint256 indexed nonce, address indexed sender, address indexed to, uint256 amount);
    event Dispatched(uint256 indexed nonce, bytes32 messageId);

    constructor(IHyperlaneMailbox mailbox_, uint32 destinationDomain_, bytes32 recipient_) {
        require(address(mailbox_) != address(0) && recipient_ != bytes32(0), "config");
        mailbox = mailbox_;
        destinationDomain = destinationDomain_;
        recipient = recipient_;
    }

    function body(uint256 n, address sender, address to, uint256 amount) public view returns (bytes memory) {
        return abi.encode(block.chainid, address(this), n, sender, to, amount);
    }

    /// The Mailbox fee for the next lock (pay amount + this).
    function quoteLock(address to, uint256 amount) external view returns (uint256) {
        return mailbox.quoteDispatch(destinationDomain, recipient, body(nonce, msg.sender, to, amount));
    }

    function lock(address to, uint256 amount) external payable returns (bytes32 messageId) {
        require(amount > 0 && to != address(0) && msg.value >= amount, "lock");
        uint256 n = nonce++;
        emit Locked(n, msg.sender, to, amount);
        messageId = mailbox.dispatch{value: msg.value - amount}(destinationDomain, recipient, body(n, msg.sender, to, amount));
        emit Dispatched(n, messageId);
    }
}

